func onItemActivated(event):
	activations += 1

	if activations == getP1():
		activations = 0
		doCooldownEffect()
		activate()

		if doubleActivationChance > 0 and Util.flip(doubleActivationChance):
			doCooldownEffect()
			activate()

		showCooldownSmooth(activations / activationsToTrigger, true)
	else:
		showCooldownSmooth(activations / activationsToTrigger, false)

	triggerTime = activationsToTrigger - activations

		invuCharges -= 1
		setState(CrownState.Active, true)
		var invuDur = getP_m("dur_invu")
		var event = character().makeInvulnerable(invuDur, self)
		buffTimer.start(invuDur)
		useMana(manaCost, event)
		Util.createPulse(activationPulse, self, global_position)

func buffEnded():
	if invuCharges > 0:
		setState(CrownState.Inactive, true)
	else:
		setState(CrownState.Used, true)

func onCombatEnd():
	buffTimer.stop()

func onShopEntered():
	onStateChanged(CrownState.Inactive)

func onStateChanged(_crownState):
